// Период: с 1 января по вчерашний день (для ежедневного запуска)
// Каждый день workflow собирает данные за вчерашний день
const periodStart = '2026-01-01';
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1); // Вчерашний день
const periodEnd = yesterday.toISOString().split('T')[0]; // Вчерашняя дата YYYY-MM-DD
const periodEndFull = new Date(yesterday);
periodEndFull.setHours(23, 59, 59, 999);
const periodEndFullISO = periodEndFull.toISOString();

// Timestamps для Instagram Insights API
const periodStartDate = new Date(periodStart + 'T00:00:00Z');
const periodEndDate = new Date(periodEnd + 'T23:59:59Z');
const periodStartTimestamp = Math.floor(periodStartDate.getTime() / 1000);
const periodEndTimestamp = Math.floor(periodEndDate.getTime() / 1000);

console.log(`📅 Период: ${periodStart} - ${periodEnd} (вчера)`);
console.log(`📅 Полный период для фильтра: ${periodStart} - ${periodEndFullISO}`);
console.log(`📅 Timestamps для Instagram API: ${periodStartTimestamp} - ${periodEndTimestamp}`);

return {
  json: {
    period_start: periodStart,
    period_end: periodEnd,
    period_end_full: periodEndFullISO,
    period_start_timestamp: periodStartTimestamp,
    period_end_timestamp: periodEndTimestamp
  }
};

// Формируем правильный URL для Supabase
const periodData = $input.first().json;
const periodStart = periodData.period_start;
const periodEnd = periodData.period_end;
const periodEndFull = periodData.period_end_full;

// Supabase требует формат: posted_at=gte.2026-01-01&posted_at=lte.2026-01-22T23:59:59.999Z
const url = `https://pyscczcuersdjvpmkiec.supabase.co/rest/v1/instagram_posts_stats?posted_at=gte.${periodStart}&posted_at=lte.${periodEndFull}&order=posted_at.asc`;

console.log(`\n🔗 Формирование URL для Supabase:`);
console.log(`   Период: ${periodStart} - ${periodEnd}`);
console.log(`   URL: ${url}`);

return {
  json: {
    url: url,
    period_start: periodStart,
    period_end: periodEnd,
    period_end_full: periodEndFull
  }
};

// Обрабатываем ответ от Supabase
const input = $input.first().json;

console.log('\n🔍 ОБРАБОТКА ОТВЕТА ОТ SUPABASE:');
console.log('   Input type:', typeof input);
console.log('   Input keys:', input ? Object.keys(input) : 'null');

// Supabase может вернуть данные в разных форматах
let posts = [];

// Вариант 1: Прямой массив
if (Array.isArray(input)) {
  posts = input;
  console.log('✅ Данные получены как массив, длина:', posts.length);
}
// Вариант 2: Объект с полем data
else if (input && Array.isArray(input.data)) {
  posts = input.data;
  console.log('✅ Данные получены из input.data, длина:', posts.length);
}
// Вариант 3: Объект с полем body (строка JSON)
else if (input && input.body) {
  try {
    const parsed = typeof input.body === 'string' ? JSON.parse(input.body) : input.body;
    posts = Array.isArray(parsed) ? parsed : (parsed ? [parsed] : []);
    console.log('✅ Данные получены из input.body, длина:', posts.length);
  } catch (e) {
    console.log('❌ Ошибка парсинга input.body:', e.message);
  }
}
// Вариант 4: Один объект
else if (input && typeof input === 'object' && !Array.isArray(input)) {
  posts = [input];
  console.log('✅ Данные получены как один объект');
}
else {
  console.log('❌ Не удалось извлечь данные из ответа');
  console.log('   Input:', JSON.stringify(input).substring(0, 500));
}

console.log(`\n📊 Итого постов: ${posts.length}`);

// Возвращаем посты для следующей ноды
return posts.map(post => ({ json: post }));

// Получаем период из предыдущего узла
const periodData = $('📅 Рассчитать период (1 янв - вчера)').first().json;
const periodStart = periodData.period_start;
const periodEnd = periodData.period_end;

// Получаем посты из ноды "🔍 Обработать ответ"
// Теперь это массив объектов { json: {...} }
const allItems = $input.all();
const posts = allItems.map(item => item.json);

console.log(`\n📊 Получено постов за период ${periodStart} - ${periodEnd}: ${posts.length}`);

if (posts.length === 0) {
  console.log('⚠️ Нет постов за этот период в instagram_posts_stats');
  console.log('   Проверь, что данные загружены через INSTAGRAM-CONTENT-INTELLIGENCE-FIXED.json');
  console.log('   Или проверь, что в таблице есть посты за период 1-22 января 2026');
  return { json: { skip: true, reason: 'no_posts', message: 'Нет постов за период 1-22 января' } };
}

// Считаем метрики
// Считаем Публикации (Reels, Carousels, обычные посты - без Stories)
const publications = posts.filter(p => {
  const mediaType = (p.media_type || '').toLowerCase();
  return !mediaType.includes('story') && mediaType !== 'stories';
}).length;

// Суммируем метрики
const totalReach = posts.reduce((sum, p) => sum + (p.reach || 0), 0);
const totalImpressions = posts.reduce((sum, p) => sum + (p.impressions || 0), 0);
const totalLikes = posts.reduce((sum, p) => sum + (p.likes || 0), 0);
const totalShares = posts.reduce((sum, p) => sum + (p.shares || 0), 0);

// Комментарии = сумма всех комментариев
const totalCommentsCount = posts.reduce((sum, p) => sum + (p.comments || 0), 0);

// Бизнес-метрики
const totalDiagnostics = posts.reduce((sum, p) => sum + (p.leads_count || 0), 0);
const totalSales = posts.reduce((sum, p) => sum + (p.paid_leads || 0), 0);
const totalRevenue = posts.reduce((sum, p) => sum + (p.revenue || 0), 0);

// Получаем подписчиков из Instagram API
// Пробуем два способа:
// 1. Текущее количество из базовой информации аккаунта
// 2. Новые подписчики за период из Insights API
let totalFollowers = 0;

try {
  // Способ 1: Получаем текущее количество подписчиков
  const followersNode = $('👥 Получить подписчиков');
  let currentFollowers = 0;

  if (followersNode) {
    const followersData = followersNode.first().json;
    console.log('\n📊 ДАННЫЕ О ПОДПИСЧИКАХ (базовая информация):');
    console.log(JSON.stringify(followersData, null, 2));

    if (followersData.error) {
      console.log('❌ Ошибка от Instagram API (базовая информация):', followersData.error.message);
    } else if (followersData.followers_count !== undefined) {
      currentFollowers = parseInt(followersData.followers_count) || 0;
      console.log(`✅ Текущее количество подписчиков: ${currentFollowers}`);
    }
  }

  // Способ 2: Получаем новых подписчиков за период из Insights API
  const followersGainedNode = $('👥 Получить новых подписчиков');
  let newFollowers = 0;

  if (followersGainedNode) {
    const gainedData = followersGainedNode.first().json;
    console.log('\n📊 ДАННЫЕ О НОВЫХ ПОДПИСЧИКАХ (Insights API):');
    console.log(JSON.stringify(gainedData, null, 2));

    if (gainedData.error) {
      console.log('❌ Ошибка от Instagram Insights API:', gainedData.error.message);
      console.log('   Код:', gainedData.error.code);
      console.log('   Тип:', gainedData.error.type);
    } else if (gainedData && gainedData.data && Array.isArray(gainedData.data)) {
      const followersMetric = gainedData.data.find(m => m.name === 'followers_gained');

      if (followersMetric && followersMetric.values && Array.isArray(followersMetric.values)) {
        console.log(`\n✅ Найдена метрика: ${followersMetric.name}`);
        console.log(`   Количество значений: ${followersMetric.values.length}`);

        // Суммируем всех новых подписчиков за период
        newFollowers = followersMetric.values.reduce((sum, v) => sum + (parseInt(v.value) || 0), 0);
        console.log(`   Новых подписчиков за период: ${newFollowers}`);
      } else {
        console.log('⚠️ Метрика followers_gained не найдена в ответе');
        console.log('   Доступные метрики:', gainedData.data.map(m => m.name).join(', '));
      }
    }
  }

  // Используем новых подписчиков за период (если есть), иначе текущее количество
  totalFollowers = newFollowers > 0 ? newFollowers : currentFollowers;

  console.log(`\n📊 ИТОГО:`);
  console.log(`   Текущее количество: ${currentFollowers}`);
  console.log(`   Новых за период: ${newFollowers}`);
  console.log(`   Используем: ${totalFollowers}`);

} catch (e) {
  console.log('❌ Ошибка получения подписчиков:', e.message);
  console.log('   Stack:', e.stack);
  totalFollowers = 0;
}

const projectId = '64c94e87-630c-470e-8ab1-8f7c8c835efa';

const result = {
  project_id: projectId,
  period_start: periodStart,
  period_end: periodEnd,
  publications: publications,
  reach: totalReach,
  comments: totalCommentsCount,
  followers: totalFollowers, // Получаем из Instagram Insights API
  diagnostics: totalDiagnostics,
  sales: totalSales,
  revenue: Math.round(totalRevenue), // БЕЗ КОПЕЕК
};

console.log(`\n✅ Агрегированные метрики за ${periodStart} - ${periodEnd}:`);
console.log(`   Публикации: ${publications}`);
console.log(`   Охват: ${(totalReach || 0).toLocaleString('ru-RU')}`);
console.log(`   Комментарии: ${totalCommentsCount}`);
console.log(`   Подписчики: ${totalFollowers}`);
console.log(`   Диагностики: ${totalDiagnostics}`);
console.log(`   Продажи: ${totalSales}`);
console.log(`   Выручка: ${(totalRevenue || 0).toLocaleString('ru-RU')}₸`);

return { json: result };

// Обрабатываем ответ от Supabase
const input = $input.first();
const responseData = input.json;
const statusCode = input.statusCode || (input.headers && input.headers.status) || null;

console.log('\n🔍 ОБРАБОТКА ОТВЕТА ОТ SUPABASE:');
console.log('   HTTP Status Code:', statusCode);
console.log('   Response type:', typeof responseData);

// Проверяем HTTP статус
if (statusCode && statusCode >= 200 && statusCode < 300) {
  console.log(`\n✅ HTTP Status ${statusCode} - Запрос успешен!`);
} else if (statusCode && statusCode >= 400) {
  console.log(`\n❌ HTTP Status ${statusCode} - Ошибка запроса!`);
}

// Проверяем, есть ли ошибка в теле ответа
if (responseData && (responseData.error || responseData.message)) {
  console.log('\n❌ ОШИБКА ОТ SUPABASE:');
  console.log('   Error:', responseData.error || responseData.message);
  console.log('   Details:', responseData.details || responseData.hint || '');

  return {
    json: {
      success: false,
      error: responseData.error || responseData.message,
      details: responseData.details || responseData.hint || '',
      status_code: statusCode,
      timestamp: new Date().toISOString()
    }
  };
}

// Если HTTP статус успешный, считаем это успехом
if (statusCode && statusCode >= 200 && statusCode < 300) {
  // Получаем исходные данные из предыдущей ноды
  const originalData = $('🧮 Рассчитать метрики').first().json;

  console.log(`\n✅ УСПЕШНО СОХРАНЕНО в content_production_stats!\n`);
  console.log(`   Период: ${originalData.period_start} - ${originalData.period_end}`);
  console.log(`   Публикации: ${originalData.publications || 0}`);
  console.log(`   Охват: ${(originalData.reach || 0).toLocaleString('ru-RU')}`);
  console.log(`   Комментарии: ${originalData.comments || 0}`);
  console.log(`   Подписчики: ${originalData.followers || 0}`);

  return {
    json: {
      success: true,
      message: `Статистика за ${originalData.period_start} - ${originalData.period_end} успешно сохранена`,
      period_start: originalData.period_start,
      period_end: originalData.period_end,
      publications: originalData.publications || 0,
      reach: originalData.reach || 0,
      comments: originalData.comments || 0,
      followers: originalData.followers || 0,
      status_code: statusCode,
      timestamp: new Date().toISOString()
    }
  };
}

// Если нет статуса, но нет ошибки - тоже считаем успехом (пустой ответ от Supabase)
if (!responseData || (Array.isArray(responseData) && responseData.length === 0) || (typeof responseData === 'object' && Object.keys(responseData).length === 0)) {
  const originalData = $('🧮 Рассчитать метрики').first().json;

  console.log(`\n✅ УСПЕШНО СОХРАНЕНО (пустой ответ от Supabase - это нормально для UPSERT)`);
  console.log(`   Период: ${originalData.period_start} - ${originalData.period_end}`);

  return {
    json: {
      success: true,
      message: `Статистика за ${originalData.period_start} - ${originalData.period_end} успешно сохранена (пустой ответ)`,
      period_start: originalData.period_start,
      period_end: originalData.period_end,
      timestamp: new Date().toISOString()
    }
  };
}

// Неизвестный формат ответа
console.log('\n⚠️ Неизвестный формат ответа от Supabase');
return {
  json: {
    success: false,
    error: 'unknown_response_format',
    status_code: statusCode,
    response: responseData,
    timestamp: new Date().toISOString()
  }
};

const result = $input.first().json;

if (result.success) {
  console.log(`\n✅ ИТОГОВЫЙ РЕЗУЛЬТАТ:`);
  console.log(`   ${result.message}`);
  console.log(`   Период: ${result.period_start} - ${result.period_end}`);
  if (result.publications !== undefined) {
    console.log(`   Публикации: ${result.publications}`);
    console.log(`   Охват: ${(result.reach || 0).toLocaleString('ru-RU')}`);
    console.log(`   Комментарии: ${result.comments || 0}`);
    console.log(`   Подписчики: ${result.followers || 0}`);
  }
} else {
  console.log(`\n❌ ОШИБКА:`);
  console.log(`   ${result.error || 'Unknown error'}`);
  if (result.details) {
    console.log(`   Details: ${result.details}`);
  }
}

return {
  json: result
};
